from modele import chapitre,E,Q,tableau
from pedagogie import page,sec,bloc

chapitre(16,'triangles','Triangles et cercle circonscrit','3 · Espace et géométrie',
'Constructions · Triangles particuliers · Somme des angles · Cercle circonscrit',
['Construire des triangles à partir de longueurs et d’angles.','Utiliser la somme des angles et les angles des triangles particuliers.','Construire le cercle circonscrit à un triangle.'],
['Compas ; rapporteur ; médiatrice d’un segment.'],[
page(1,'Construire et discuter les données',
bloc('savoirfaire',r'Pour construire ABC avec $AB=6$ cm, $AC=4$ cm et $BC=5$ cm : tracer [AB] ; tracer un arc de centre A et de rayon 4 cm, puis un arc de centre B et de rayon 5 cm. Leur point d’intersection est C.','Trois longueurs'),
r'@FIG:cours-construction-triangle@',
bloc('propriete',r'Trois longueurs ne permettent pas toujours de construire un triangle : la plus grande doit être plus petite que la somme des deux autres. Avec 3 cm, 4 cm et 8 cm, les arcs ne se rencontrent pas, car $3+4<8$.'),
sec(2,'Triangles particuliers et angles'),
bloc('definition',r'Un triangle isocèle a deux côtés de même longueur : ses deux angles à la base ont la même mesure. Un triangle équilatéral a trois côtés de même longueur : ses trois angles mesurent $60^\circ$. Un triangle rectangle a un angle droit.')),
page(3,'Somme des angles d’un triangle',
bloc('propriete',r'Dans tout triangle, la somme des mesures des trois angles vaut $180^\circ$.'),
r'@FIG:cours-somme-angles@',
bloc('exemple',r'Si deux angles mesurent $48^\circ$ et $67^\circ$, le troisième mesure $180-48-67=65^\circ$. Dans un triangle rectangle, les deux angles aigus ont une somme de $90^\circ$.'),
sec(4,'Médiatrices et cercle circonscrit'),
bloc('propriete',r'Les trois médiatrices des côtés d’un triangle se coupent en un même point O. Ce point est à égale distance des trois sommets : c’est le centre du cercle qui passe par A, B et C, appelé cercle circonscrit au triangle.'),
r'@FIG:cours-cercle-circonscrit@',
bloc('savoirfaire',r'Deux médiatrices suffisent : leur point d’intersection est le centre O ; le rayon est OA.','Construire le cercle circonscrit')),
],[
E('Le troisième angle',r'Dans le triangle ABC, $\widehat{A}=48^\circ$ et $\widehat{B}=67^\circ$. Calculer $\widehat{C}$.',r'$\widehat{C}=180-48-67=\res{65^\circ}$.','Utiliser la somme des angles.','assert 180-48-67==65',figure='tri-1'),
E('Triangle isocèle',r'Le triangle ABC est isocèle en A et $\widehat{A}=40^\circ$. Calculer les deux autres angles.',r'Les angles à la base sont égaux et leur somme vaut $180-40=140^\circ$ : chacun mesure $\res{70^\circ}$.','Partager ce qui reste en deux.','assert (180-40)/2==70',figure='tri-2'),
E('Triangle équilatéral',r'Un triangle équilatéral a des côtés de 4 cm. Donner la mesure de ses angles et son périmètre.',r'Ses trois angles sont égaux : $180:3=\res{60^\circ}$. Périmètre : $3\times4=\res{12\ \mathrm{cm}}$.','Trois angles égaux, trois côtés égaux.','assert 180/3==60 and 3*4==12',figure='tri-3'),
E('Triangle rectangle',r'Le triangle ABC est rectangle en C et $\widehat{A}=35^\circ$. Calculer $\widehat{B}$.',r'Les deux angles aigus ont une somme de $90^\circ$ : $\widehat{B}=90-35=\res{55^\circ}$.','Utiliser l’angle droit.','assert 180-90-35==55',figure='tri-4'),
E('Trois longueurs',r'Construire le triangle ABC tel que $AB=6$ cm, $AC=4$ cm et $BC=5$ cm.',r'On trace [AB], puis l’arc de centre A de rayon 4 cm et l’arc de centre B de rayon 5 cm ; ils se coupent en C. La construction figure en vert.','Deux arcs de cercle donnent le troisième sommet.','assert 6<4+5 and 5<4+6 and 4<5+6',figure='tri-5'),
E('Possible ou pas ?',r'Peut-on construire un triangle dont les côtés mesurent 3 cm, 4 cm et 8 cm ? Et 5 cm, 6 cm et 10 cm ?',r'$3+4=7<8$ : les arcs ne se rencontrent pas, c’est $\res{\text{impossible}}$, comme le montre la figure. $5+6=11>10$ : c’est $\res{\text{possible}}$.','Comparer le plus grand côté à la somme des deux autres.','assert 3+4<8 and 5+6>10',figure='tri-6'),
E('Deux côtés et un angle',r'Construire le triangle ABC tel que $AB=5$ cm, $\widehat{BAC}=60^\circ$ et $AC=3$ cm.',r'On trace [AB], on construit l’angle de $60^\circ$ en A, puis on place C à 3 cm de A sur le second côté. La construction est en vert.','Construire l’angle avant de reporter la longueur.','assert 0<60<180',figure='tri-7'),
E('Un côté et deux angles',r'Construire le triangle ABC tel que $BC=6$ cm, $\widehat{B}=50^\circ$ et $\widehat{C}=60^\circ$. Calculer $\widehat{A}$ sans le mesurer.',r'Les deux demi-droites tracées depuis B et C se coupent en A (en vert). $\widehat{A}=180-50-60=\res{70^\circ}$.','Deux angles et le côté qui les relie.','assert 180-50-60==70',figure='tri-8'),
E('Angles d’un isocèle',r'Le triangle ABC est isocèle en A et ses angles à la base mesurent $72^\circ$. Calculer l’angle au sommet $\widehat{A}$.',r'$\widehat{A}=180-72-72=\res{36^\circ}$.','Les deux angles à la base sont égaux.','assert 180-2*72==36',figure='tri-9'),
E('Construire le cercle circonscrit',r'Reproduire le triangle ABC, puis construire son cercle circonscrit.',r'On trace les médiatrices de [AB] et de [BC] ; elles se coupent en O. Le cercle de centre O et de rayon OA passe par A, B et C. La construction est en vert ; la troisième médiatrice passe aussi par O.','Deux médiatrices donnent le centre.','assert True',figure='tri-10'),
E('Trois villages',r'Trois villages A, B et C veulent installer une antenne à la même distance des trois. Où la placer ?',r'L’antenne doit être à égale distance de A et de B, et de B et de C : elle est sur deux médiatrices. On la place en O, $\res{\text{centre du cercle circonscrit}}$ au triangle ABC, en vert.','Traduire chaque équidistance par une médiatrice.','assert True',figure='tri-11'),
E('Le cercle d’un triangle rectangle',r'Le triangle ABC est rectangle en A. Construire son cercle circonscrit. Que remarque-t-on sur la position du centre ?',r'Les médiatrices se coupent au $\res{\text{milieu de [BC]}}$ : le centre est sur le côté opposé à l’angle droit, et [BC] est un diamètre du cercle.','Construire, puis observer.','assert True',figure='tri-12'),
E('Isocèle et équilatéral',r'Le triangle ABC est isocèle en A avec $\widehat{B}=65^\circ$. On construit, de l’autre côté de (AC), le triangle équilatéral ACD. Calculer $\widehat{BAC}$, puis $\widehat{BAD}$.',r'$\widehat{C}=\widehat{B}=65^\circ$, donc $\widehat{BAC}=180-130=\res{50^\circ}$. $\widehat{CAD}=60^\circ$, d’où $\widehat{BAD}=50+60=\res{110^\circ}$.','Enchaîner les propriétés des deux triangles.','assert 180-2*65==50 and 50+60==110',figure='tri-13'),
E('Dans un triangle équilatéral',r'ABC est un triangle équilatéral. La bissectrice de l’angle $\widehat{A}$ coupe le côté [BC] en H. Calculer $\widehat{BAH}$, puis $\widehat{AHB}$.',r'$\widehat{BAH}=60:2=\res{30^\circ}$. Dans le triangle ABH : $\widehat{AHB}=180-60-30=\res{90^\circ}$. La bissectrice est perpendiculaire à [BC].','Utiliser la bissectrice, puis la somme des angles.','assert 60/2==30 and 180-60-30==90',figure='tri-14'),
E('Deux angles obtus ?',r'Zoé veut construire un triangle ABC avec $\widehat{A}=100^\circ$ et $\widehat{B}=95^\circ$. Est-ce possible ?',r'$100+95=195$, déjà plus que $180^\circ$ : c’est $\res{\text{impossible}}$. La figure le confirme : les deux côtés s’écartent et ne se rencontrent jamais. Un triangle a au plus un angle obtus.','Utiliser la somme des angles.','assert 100+95>180',figure='tri-15')
],reperes=['Construire des triangles','Triangles particuliers','Somme des angles','Médiatrices et cercle circonscrit'],deco='geometrie')

chapitre(17,'symetrie-axiale','Symétrie axiale','3 · Espace et géométrie',
'Axe · Symétrique d’un point · Constructions · Propriétés',
['Connaître la définition du symétrique d’un point par rapport à une droite.','Construire des symétriques sur quadrillage, papier pointé et papier uni.','Utiliser les propriétés de la symétrie pour construire et justifier.'],
['Médiatrice ; perpendiculaires ; report de longueurs au compas.'],[
page(1,'Reconnaître un axe et des points associés',
bloc('definition',r"Le symétrique d’un point M par rapport à une droite (d) est le point M' tel que (d) soit la médiatrice du segment [MM']. Si M est sur (d), son symétrique est M lui-même."),
r'@FIG:cours-sym-point@',
bloc('definition',r'Une figure a un axe de symétrie si, pliée le long de cet axe, ses deux parties se superposent exactement. Un rectangle a 2 axes, un carré 4, un triangle équilatéral 3 ; un cercle en a une infinité : toutes les droites qui passent par son centre.'),
sec(2,'Construire sur supports gradués'),
bloc('savoirfaire',r'Pour un axe horizontal ou vertical, on compte les carreaux de M jusqu’à l’axe, perpendiculairement à l’axe, puis on reporte le même nombre de carreaux de l’autre côté. Pour un axe qui suit les diagonales du quadrillage, on avance en diagonale à travers les carreaux. Sur papier pointé, on compte les points de la même façon.','Quadrillage et papier pointé')),
page(3,'Construire sur papier uni',
bloc('savoirfaire',r"On trace la perpendiculaire à (d) passant par M ; elle coupe (d) en H. Au compas, on reporte la longueur MH de l’autre côté de (d) : on obtient M'. Au compas seul : avec deux points A et B de (d), M' est le second point commun au cercle de centre A passant par M et au cercle de centre B passant par M.",'À l’équerre et au compas'),
r'@FIG:cours-sym-triangle@',
sec(4,'Utiliser les propriétés de la symétrie'),
bloc('propriete',r'La symétrie axiale conserve les longueurs, les angles, l’alignement et les aires. L’image d’un segment est un segment de même longueur ; l’image d’une droite est une droite ; l’image d’un cercle est un cercle de même rayon.'),
bloc('savoirfaire',r'Pour construire l’image d’un polygone, on construit les images de ses sommets, puis on les relie dans le même ordre. L’image d’un cercle se construit avec l’image de son centre et le même rayon.','Construire l’image d’une figure')),
],[
E('Combien d’axes ?',r'Donner le nombre d’axes de symétrie de chaque figure : rectangle, carré, triangle isocèle, losange, triangle quelconque.',r'Rectangle : $\res2$. Carré : $\res4$. Triangle isocèle : $\res1$. Losange : $\res2$, ses diagonales. Triangle quelconque : $\res0$. Les axes sont tracés en vert.','Imaginer un pliage qui superpose les deux moitiés.','assert [2,4,1,2,0]==[2,4,1,2,0]',figure='sym-1'),
E('Axe vertical',r"Reproduire la figure et le point A, puis construire leurs symétriques par rapport à l’axe vertical.",r"On compte les carreaux horizontalement jusqu’à l’axe et on les reporte de l’autre côté. L’image et le point $A'$ figurent en vert.",'Compter perpendiculairement à l’axe.','assert True',figure='sym-2'),
E('Axe horizontal',r"Construire le symétrique du drapeau et du point B par rapport à l’axe horizontal.",r"On compte les carreaux verticalement : chaque point est reporté à la même distance, de l’autre côté de l’axe. L’image et $B'$ figurent en vert ; le drapeau se retrouve tête en bas.",'Compter perpendiculairement à l’axe.','assert True',figure='sym-3'),
E('Axe en diagonale',r'L’axe suit la diagonale des carreaux. Construire le symétrique de la figure et du point C.',r"On avance en diagonale à travers les carreaux, perpendiculairement à l’axe. Les écarts horizontaux et verticaux s’échangent ; l’image et $C'$ figurent en vert.",'Suivre les diagonales des carreaux.','assert True',figure='sym-4'),
E('Papier pointé',r'Construire le symétrique de la figure par rapport à la droite (d), sur papier pointé.',r'On compte les intervalles entre les points, perpendiculairement à (d), et on les reporte. L’image est en vert ; les longueurs sont conservées.','Les points jouent le rôle des carreaux.','assert True',figure='sym-5'),
E('Symétrique d’un point',r"Reproduire la droite (d) et le point A sur papier uni, puis construire le symétrique $A'$ de A par rapport à (d), à l’équerre et au compas.",r"On trace la perpendiculaire à (d) passant par A ; elle coupe (d) en H. On reporte la longueur AH au compas de l’autre côté de (d) : c’est $A'$, en vert.",'Perpendiculaire, puis report de longueur.','assert True',figure='sym-6'),
E('Image d’un segment',r"Le segment [AB] mesure 4 cm. Construire son symétrique $[A'B']$ par rapport à la droite (d). Quelle est la longueur $A'B'$ ?",r"On construit $A'$ et $B'$, puis on les relie (en vert). La symétrie conserve les longueurs : $\res{A'B'=4\ \mathrm{cm}}$.",'Construire les images des extrémités.','assert True',figure='sym-7'),
E('Image d’un cercle',r"Construire le symétrique du cercle de centre O et de rayon $1{,}5$ cm par rapport à la droite (d).",r"On construit le symétrique $O'$ du centre, puis le cercle de centre $O'$ et de même rayon, $\res{1{,}5\ \mathrm{cm}}$ (en vert).",'Image du centre et même rayon.','assert True',figure='sym-8'),
E('Compléter la figure',r'La droite (d) est un axe de symétrie de la maison. Compléter le dessin.',r'On construit le symétrique de chaque sommet par rapport à (d), puis on relie dans le même ordre. La moitié manquante est en vert.','Compléter point par point.','assert True',figure='sym-9'),
E('Retrouver l’axe',r"Le triangle $A'B'C'$ est le symétrique du triangle ABC par rapport à une droite (d) effacée. Retrouver la droite (d).",r"(d) est la médiatrice du segment $[AA']$. On la construit au compas ; elle est aussi la médiatrice de $[BB']$ et de $[CC']$, ce qui sert de contrôle. Elle figure en vert.",'L’axe est la médiatrice d’un segment point-image.','assert True',figure='sym-10'),
E('Ce que la symétrie conserve',r"Le triangle $A'B'C'$ est le symétrique de ABC. On sait que $AB=5$ cm, $\widehat{ABC}=40^\circ$ et que l’aire de ABC vaut 6 cm$^2$. Donner, sans mesurer, $A'B'$, la mesure de l’angle de sommet $B'$ et l’aire de $A'B'C'$.",r"La symétrie conserve longueurs, angles et aires : $\res{A'B'=5\ \mathrm{cm}}$, l’angle de sommet $B'$ mesure $\res{40^\circ}$ et l’aire vaut $\res{6\ \mathrm{cm}^2}$.",'Utiliser les propriétés de conservation.','assert True',figure='sym-11'),
E('Les points de l’axe',r"Le segment [MN] coupe la droite (d) en I. Construire son symétrique $[M'N']$. Par quel point passe-t-il forcément ? Pourquoi ?",r"Le point I est sur (d) : il est son propre symétrique. Comme I est sur [MN], son image I est sur $[M'N']$ : le segment image passe par $\res I$. L’alignement est conservé.",'Un point de l’axe ne bouge pas.','assert True',figure='sym-12'),
E('Le billard',r"On veut envoyer la boule A sur la bande (d) pour qu’elle rebondisse vers la boule B. Construire le symétrique $A'$ de A par rapport à (d), puis le point I où la droite $(A'B)$ coupe (d). Tracer le trajet A–I–B.",r"La symétrie conserve les longueurs : $AI=A'I$. Le trajet A–I–B a donc la même longueur que $A'$–I–B, qui est un segment. Le point d’impact I est en vert ; c’est le chemin le plus court qui touche la bande.",'Remplacer A par son symétrique.','assert True',figure='sym-13'),
E('Lettres symétriques',r'Pour chacune des lettres H, A, E, N et X, dessinées ici en bâtons, donner le nombre d’axes de symétrie.',r'H : $\res2$ ; A : $\res1$, vertical ; E : $\res1$, horizontal ; N : $\res0$ ; X : $\res2$. Les axes sont en vert.','Chercher les pliages qui superposent.','assert [2,1,1,0,2]==[2,1,1,0,2]',figure='sym-14'),
E('Un retournement',r'Malo pense que la symétrie axiale fait seulement glisser une figure. Observer le drapeau et son image. A-t-il raison ?',r'$\res{\text{Non}}$ : le drapeau pointait vers la droite, son image pointe vers la gauche. La symétrie retourne la figure, comme un miroir, tout en conservant ses longueurs et ses angles.','Comparer l’orientation des deux figures.','assert True',figure='sym-15')
],reperes=['Axes de symétrie d’une figure','Constructions sur quadrillage et papier pointé','Constructions sur papier uni','Propriétés de la symétrie'],deco='geometrie')

chapitre(18,'solides-volumes','Solides, assemblages et volumes','3 · Espace et géométrie',
'Solides usuels · Vues · Cubes cachés · Centimètre cube',
['Reconnaître les solides usuels et utiliser leur vocabulaire.','Passer d’un assemblage de cubes à ses vues, et inversement.','Déterminer et comparer des volumes en centimètres cubes.'],
['Solides et patrons du cours moyen ; dénombrement organisé.'],[
page(1,'Reconnaître et décrire les solides usuels',
bloc('definition',r'Le cube et le pavé droit ont 6 faces rectangulaires. Un prisme droit a deux bases polygonales identiques et des faces latérales rectangulaires. Une pyramide a une base polygonale et des faces triangulaires qui se rejoignent en un sommet. Le cylindre, le cône et la boule ont des surfaces courbes.'),
r'@FIG:cours-solides@',
bloc('propriete',r'Les faces d’un polyèdre sont planes ; deux faces se rencontrent sur une arête ; les arêtes se rejoignent en des sommets. Le pavé droit a 6 faces, 12 arêtes et 8 sommets.'),
sec(2,'Comprendre les vues et les perspectives'),
bloc('definition',r'Une perspective représente un solide sur une feuille ; les arêtes cachées y sont en pointillés. Une vue de face, de dessus ou de côté montre ce que l’on voit en regardant le solide dans une seule direction.')),
page(3,'Dénombrer les cubes visibles et cachés',
r'@FIG:cours-assemblage-vues@',
bloc('savoirfaire',r'On compte étage par étage, sans oublier les cubes cachés qui portent ceux du dessus. Sur la vue de dessus, on peut écrire dans chaque case le nombre de cubes empilés : le total des nombres donne le nombre de cubes.','Compter par étages'),
sec(4,'Mesurer un volume en centimètres cubes'),
bloc('definition',r'Le volume d’un solide mesure la place qu’il occupe dans l’espace. 1 cm$^3$ est le volume d’un cube de 1 cm d’arête. Un assemblage de 14 cubes de 1 cm d’arête a un volume de 14 cm$^3$.'),
bloc('attention',r'Deux solides de formes différentes peuvent avoir le même volume : il suffit qu’ils contiennent le même nombre de cubes unités.')),
],[
E('Nommer les solides',r'Nommer chacun des six solides numérotés.',r'1 : $\res{\text{pyramide}}$ à base carrée. 2 : $\res{\text{cylindre}}$. 3 : $\res{\text{cône}}$. 4 : $\res{\text{prisme droit}}$ à base triangulaire. 5 : $\res{\text{boule}}$. 6 : $\res{\text{pavé droit}}$.','Observer les bases et les faces.','assert True',figure='sol-1'),
E('Faces, arêtes, sommets',r'Compter les faces, les arêtes et les sommets du pavé droit, puis de la pyramide à base carrée.',r'Pavé droit : $\res{6}$ faces, $\res{12}$ arêtes, $\res{8}$ sommets. Pyramide : $\res5$ faces, $\res8$ arêtes, $\res5$ sommets.','Compter de façon organisée : base, puis côtés.','assert (6,12,8)==(6,12,8) and (1+4,4+4,4+1)==(5,8,5)',figure='sol-2'),
E('Un petit cube de cubes',r'Le grand cube est formé de cubes de 1 cm d’arête. Combien de petits cubes le composent ? Quel est son volume ?',r'Deux étages de $2\times2=4$ cubes : $\res8$ cubes, soit un volume de $\res{8\ \mathrm{cm}^3}$.','Compter étage par étage.','assert 2*2*2==8',figure='sol-3'),
E('La bonne vue de dessus',r'Parmi les vues 1, 2 et 3, laquelle est la vue de dessus de l’assemblage ?',r'De dessus, on voit une case pour chaque colonne de cubes : trois cases en ligne et une case en arrière, à gauche. C’est la $\res{\text{vue 2}}$.','Imaginer le regard d’en haut.','assert True',figure='sol-4'),
E('L’escalier',r'L’escalier est formé de cubes de 1 cm d’arête. Quel est son volume ?',r'Les trois marches comptent $3+2+1=\res6$ cubes : volume $\res{6\ \mathrm{cm}^3}$.','Compter colonne par colonne.','assert 3+2+1==6',figure='sol-5'),
E('Les cubes cachés',r'L’assemblage est formé de trois étages pleins : un carré de 3 sur 3, un carré de 2 sur 2, puis un cube. Combien de cubes compte-t-il ? Combien sont cachés ?',r'$9+4+1=\res{14}$ cubes. Les 4 cubes du premier étage situés sous le carré de 2 sur 2 ne se voient pas : $\res4$ cubes sont cachés, et l’on en voit 10.','Compter étage par étage.','assert 9+4+1==14 and 14-10==4',figure='sol-6'),
E('Dessiner les vues',r'Dessiner sur quadrillage la vue de face, la vue de dessus et la vue de droite de l’assemblage.',r'Les trois vues sont en vert : de face, deux colonnes de hauteurs 2 et 1 ; de dessus, un carré de 2 sur 2 ; de droite, deux colonnes de hauteurs 2 et 1.','Une case par colonne visible dans la direction du regard.','assert True',figure='sol-7'),
E('Le plan coté',r'La vue de dessus indique dans chaque case le nombre de cubes empilés. Combien de cubes compte l’assemblage ? Quel est son volume ?',r'$3+2+1+2+1+1=\res{10}$ cubes, soit $\res{10\ \mathrm{cm}^3}$.','Additionner les nombres des cases.','assert 3+2+1+2+1+1==10',figure='sol-8'),
E('Comparer deux volumes',r'Les deux assemblages sont formés de cubes identiques. Lequel a le plus grand volume ?',r'A : $2\times3+3=9$ cubes. B : $2\times2\times2=8$ cubes. $\res{\text{A}}$ a le plus grand volume, d’un cube.','Compter les deux assemblages.','assert 2*3+3==9 and 2*2*2==8',figure='sol-9'),
E('Compléter en grand cube',r'L’assemblage compte 20 cubes. Combien faut-il en ajouter pour obtenir un cube de 3 cubes d’arête ?',r'Un cube de 3 sur 3 sur 3 contient $3\times3\times3=27$ cubes : il faut en ajouter $27-20=\res7$.','Comparer au cube complet.','assert 27-20==7',figure='sol-10'),
E('La boîte de sucres',r'Des morceaux de sucre de 1 cm$^3$ remplissent une boîte : 4 sucres en longueur, 3 en largeur et 2 en hauteur. Combien de sucres contient la boîte ? Quel est son volume ?',r'Un étage : $4\times3=12$ sucres ; deux étages : $\res{24}$ sucres. Volume : $\res{24\ \mathrm{cm}^3}$.','Compter un étage, puis multiplier par le nombre d’étages.','assert 4*3*2==24',figure='sol-11'),
E('Le mur percé',r'Un mur est formé de cubes de 1 dm d’arête : 6 cubes de long, 4 de haut et 1 d’épaisseur, avec une fenêtre de 2 cubes. Combien de cubes compte le mur ?',r'Mur plein : $6\times4=24$ cubes. Moins la fenêtre : $24-2=\res{22}$ cubes.','Compléter, puis retirer.','assert 6*4-2==22',figure='sol-12'),
E('Le grand cube peint',r'Un cube de 3 cubes d’arête est peint sur toutes ses faces, puis séparé en 27 petits cubes. Combien de petits cubes ont 3 faces peintes ? 2 faces ? 1 face ? Aucune ?',r'Les 8 cubes des coins ont $\res3$ faces peintes ($\res8$ cubes). Les cubes du milieu des 12 arêtes en ont 2 ($\res{12}$ cubes). Les centres des 6 faces en ont 1 ($\res6$ cubes). Le cube central n’en a aucune ($\res1$ cube). Contrôle : $8+12+6+1=27$.','Classer les petits cubes selon leur position.','assert 8+12+6+1==27',figure='sol-13'),
E('Des vues à l’assemblage',r'On donne la vue de dessus, la vue de face et la vue de droite d’un assemblage de cubes posé sur une table. Combien de cubes le composent ?',r'Vue de dessus : 4 colonnes. La vue de face et la vue de droite n’autorisent qu’une seule colonne de 2 cubes, en arrière à gauche ; les trois autres colonnes ont 1 cube. Total : $2+1+1+1=\res5$ cubes.','Croiser les informations des trois vues.','assert 2+1+1+1==5',figure='sol-14'),
E('Même volume ?',r'Chloé affirme : « Les deux assemblages n’ont pas la même forme, donc ils n’ont pas le même volume. » A-t-elle raison ?',r'Chacun compte 6 cubes : ils ont le même volume, $\res{6\ \mathrm{cm}^3}$. Elle a $\res{\text{tort}}$ : la forme change, le volume non.','Compter les cubes unités.','assert 6==6',figure='sol-15')
],reperes=['Reconnaître les solides usuels','Vues et perspectives','Dénombrer des assemblages de cubes','Volumes en centimètres cubes'],deco='espace')
